package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.DocumentHelper.*;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class Element_equals_TriageGen2Test {

    @Test
    public void testEqualsElement() {
        Element elem1 = createElement("div");
        Element elem2 = createElement("div");
        assertTrue(elem1.equals(elem2));
    }

    @Test
    public void testEqualsObject() {
        Element elem1 = createElement("div");
        Object obj = elem1;
        assertTrue(elem1.equals(obj));
    }

    @Test
    public void testNotEqualsElement() {
        Element elem1 = createElement("div");
        Element elem2 = createElement("p");
        assertFalse(elem1.equals(elem2));
    }

    @Test
    public void testNullEqualsObject() {
        Element elem = createElement("div");
        assertFalse(elem.equals(null));
    }

    @Test
    public void testNotSameClassEqualsObject() {
        Object obj = new Object();
        Element elem = createElement("div");
        assertFalse(elem.equals(obj));
    }

    @Test
    public void testNotEqualsSuperclass() {
        Element elem1 = createElement("div");
        Node node = new Node();
        assertFalse(elem1.equals(node));
    }

    @Test
    public void testEqualsSameObject() {
        Element elem = createElement("div");
        assertTrue(elem.equals(elem));
    }

    @Test
    public void testNotEqualsDifferentType() {
        Element elem = createElement("div");
        String str = "hello";
        assertFalse(elem.equals(str));
    }
}
